// Calculo dinamico de Stock de Seguridad (SS) y Punto de Reorden (PR)
// Formulas Ejercicio A5: SS = (d_max - d_prom) * L  |  PR = (d_prom * L) + SS
const items = $input.all();
return items.map((item) => {
  const d = item.json;
  const dProm = Number(d.demanda_diaria_prom || 40);
  const dMax = Number(d.demanda_diaria_max || 55);
  const L = Number(d.tiempo_entrega_dias || 3);
  const stockActual = Number(d.saldo_resultante_material || 155);

  const stockSeguridad = (dMax - dProm) * L;
  const puntoReorden = (dProm * L) + stockSeguridad;
  const bajoPuntoReorden = stockActual <= puntoReorden;

  return {
    json: {
      ...d,
      stock_seguridad: stockSeguridad,
      punto_reorden: puntoReorden,
      stock_actual: stockActual,
      bajo_punto_reorden: bajoPuntoReorden,
      deficit_unidades: bajoPuntoReorden ? (puntoReorden - stockActual) : 0
    }
  };
});

// Regla de deteccion de Compras Duplicadas y Fraccionamiento (Ejercicio A3)
// Criterio: Mismo proveedor + Mismo articulo normalizado + Diferencia <= 3 dias + Variacion cantidad <= 10%
const ordenes = $input.all().map(i => i.json);
const sospechosas = [];

for (let i = 0; i < ordenes.length; i++) {
  for (let j = i + 1; j < ordenes.length; j++) {
    const a = ordenes[i];
    const b = ordenes[j];
    if (a.proveedor_id === b.proveedor_id && a.material_id === b.material_id) {
      const diffDias = Math.round(Math.abs(new Date(a.fecha_emision) - new Date(b.fecha_emision)) / 86400000);
      const maxCant = Math.max(a.cantidad, b.cantidad);
      const diffPct = ((Math.abs(a.cantidad - b.cantidad) / maxCant) * 100);
      if (diffDias <= 3 && diffPct <= 10) {
        sospechosas.push({
          par: `${a.numero_oc} <-> ${b.numero_oc}`,
          diferencia_dias: diffDias,
          variacion_cantidad_pct: Number(diffPct.toFixed(2)),
          monto_comprometido_colones: b.monto_total_colones,
          evade_umbral_gerencia: (a.monto_total_colones + b.monto_total_colones) > 2000000
        });
      }
    }
  }
}
return sospechosas.map(s => ({ json: s }));
